// Lee el total de la primera página (activas) y genera un item por cada página necesaria
const p1 = $input.first().json;
const total = p1.paging?.total ?? 0;
const token = $('Edit Fields').first().json['Access Token'];
const sellerId = $('Edit Fields').first().json.seller_id;
const limit = 50;
const status = 'active';

if (total === 0) return [];

const out = [];
for (let offset = 0; offset < total; offset += limit) {
  out.push({ json: { offset, limit, token, sellerId, status } });
}
return out;

// Lee el total de la primera página (pausadas) y genera un item por cada página necesaria
const p1 = $input.first().json;
const total = p1.paging?.total ?? 0;
const token = $('Edit Fields').first().json['Access Token'];
const sellerId = $('Edit Fields').first().json.seller_id;
const limit = 50;
const status = 'paused';

if (total === 0) return [];

const out = [];
for (let offset = 0; offset < total; offset += limit) {
  out.push({ json: { offset, limit, token, sellerId, status } });
}
return out;

// Junta los results de todas las páginas (activas + pausadas), deduplica IDs y arma batches de 20
const token = $('Edit Fields').first().json['Access Token'];
const allIds = [];
const seen = new Set();
for (const item of $input.all()) {
  const results = item.json.results || [];
  for (const id of results) {
    if (!seen.has(id)) {
      seen.add(id);
      allIds.push(id);
    }
  }
}
if (allIds.length === 0) return [];
const out = [];
for (let i = 0; i < allIds.length; i += 20) {
  out.push({ json: { ids_csv: allIds.slice(i, i + 20).join(','), token } });
}
return out;

// La respuesta de /items?ids=... puede llegar como array o como items separados.
// El status (active/paused) viene directo del detalle de ML: es el dato real y actual.
// user_product_id (doc oficial: stock distribuido / stock multi-origen) indica que el item
// (o esa variacion puntual) separa su stock por ubicacion (Full vs deposito propio); hay que
// consultarlo aparte (siguiente nodo) via /user-products/{id}/stock, porque available_quantity
// aca puede ser un agregado que no distingue Full de deposito propio.
//
// MLA + variaciones (MLU): cuando el item tiene b.variations, el stock y el precio reales
// viven en CADA variacion (el nivel raiz del item no tiene stock propio), y cada variacion
// puede tener su propio user_product_id. Por eso expandimos una fila por variacion en vez de
// una sola fila agregada para todo el MLA.
const results = [];
for (const item of $input.all()) {
  const data = item.json;
  const entries = Array.isArray(data) ? data : [data];
  for (const r of entries) {
    if (r && r.code === 200 && r.body) {
      const b = r.body;
      const base = {
        item_id: b.id,
        title: b.title,
        currency_id: b.currency_id,
        condition: b.condition,
        status: b.status,
        listing_type_id: b.listing_type_id,
        logistic_type: b.shipping?.logistic_type ?? null,
        permalink: b.permalink
      };
      const variaciones = Array.isArray(b.variations) ? b.variations : [];
      if (variaciones.length > 0) {
        for (const v of variaciones) {
          const etiqueta = (v.attribute_combinations || [])
            .map(a => a.value_name)
            .filter(Boolean)
            .join(' / ');
          results.push({
            json: {
              ...base,
              variation_id: String(v.id),
              variant_label: etiqueta || null,
              price: v.price ?? b.price,
              available_quantity: v.available_quantity ?? 0,
              sold_quantity: v.sold_quantity ?? 0,
              user_product_id: v.user_product_id ?? b.user_product_id ?? null
            }
          });
        }
      } else {
        results.push({
          json: {
            ...base,
            variation_id: null,
            variant_label: null,
            price: b.price,
            available_quantity: b.available_quantity,
            sold_quantity: b.sold_quantity,
            user_product_id: b.user_product_id ?? null
          }
        });
      }
    }
  }
}
return results;

// Doc oficial ML: "Stock distribuido" / "Stock multi-origen".
// GET /user-products/{user_product_id}/stock devuelve locations[] con:
//   type: "meli_facility"      -> stock Full (lo administra ML)
//   type: "seller_warehouse" / "selling_address" -> deposito propio (lo administra el vendedor)
// Sin user_product_id, el item no participa de multi-origen: available_quantity YA es
// el numero correcto (deposito propio si no es Full, o Full puro si logistic_type=fulfillment).
//
// Se consulta en LOTES EN PARALELO (no uno por uno) y se deduplica user_product_id por si
// varias publicaciones (variantes) comparten el mismo producto de usuario.
const token = $('Edit Fields').first().json['Access Token'];
const items = $input.all().map(i => ({ ...i.json }));

const idsUnicos = [...new Set(items.filter(it => it.user_product_id).map(it => it.user_product_id))];
const CONCURRENCIA = 15;
const infoPorUserProduct = new Map();

for (let i = 0; i < idsUnicos.length; i += CONCURRENCIA) {
  const lote = idsUnicos.slice(i, i + CONCURRENCIA);
  const respuestas = await Promise.all(lote.map(async (upId) => {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://api.mercadolibre.com/user-products/${upId}/stock`,
        headers: { Authorization: `Bearer ${token}` },
        json: true,
      });
      const locations = resp?.locations || [];
      const full = locations.filter(l => l.type === 'meli_facility');
      const deposito = locations.filter(l => l.type === 'seller_warehouse' || l.type === 'selling_address');
      return [upId, {
        stock_full: full.length > 0 ? full.reduce((s, l) => s + (l.quantity || 0), 0) : null,
        stock_deposito: deposito.length > 0 ? deposito.reduce((s, l) => s + (l.quantity || 0), 0) : null,
      }];
    } catch (e) {
      return [upId, null];
    }
  }));
  for (const [upId, valor] of respuestas) infoPorUserProduct.set(upId, valor);
}

return items.map(it => {
  const info = it.user_product_id ? infoPorUserProduct.get(it.user_product_id) : null;
  if (info) {
    return { json: { ...it, stock_full: info.stock_full, stock_deposito: info.stock_deposito } };
  }
  const esFullPuro = it.logistic_type === 'fulfillment';
  return {
    json: {
      ...it,
      stock_full: esFullPuro ? Number(it.available_quantity || 0) : null,
      stock_deposito: esFullPuro ? null : Number(it.available_quantity || 0),
    },
  };
});
